import{_ as n,o as r,c as a,a3 as i}from"./chunks/framework.z_KJ15Ep.js";const o=JSON.parse('{"title":"Datenbanken verbinden, sichern und wiederherstellen","description":"","frontmatter":{},"headers":[],"relativePath":"administration/datenbanken.md","filePath":"administration/datenbanken.md"}'),t={name:"administration/datenbanken.md"};function d(l,e,h,s,b,u){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="datenbanken-verbinden-sichern-und-wiederherstellen" tabindex="-1">Datenbanken verbinden, sichern und wiederherstellen <a class="header-anchor" href="#datenbanken-verbinden-sichern-und-wiederherstellen" aria-label="Permalink to &quot;Datenbanken verbinden, sichern und wiederherstellen&quot;">​</a></h1><p>Verbinden Sie SchILD-NRW mit einer vorhandenen Datenbank oder legen Sie ein neues Schema an. Unterscheiden Sie außerdem Arbeitssicherung, Wiederherstellung und Import in ein anderes Schema.</p><h2 id="eine-datenbank-bereitstellen" tabindex="-1">Eine Datenbank bereitstellen <a class="header-anchor" href="#eine-datenbank-bereitstellen" aria-label="Permalink to &quot;Eine Datenbank bereitstellen&quot;">​</a></h2><p>Datenbanken werden im <a href="https://doku.svws-nrw.de/adminclient/" target="_blank" rel="noreferrer">SVWS-AdminClient</a> angelegt, migriert und schemaübergreifend importiert. Diese root-pflichtigen Funktionen gehören nicht zur Oberfläche von SchILD-NRW 3.6.0.</p><p>Die Anleitung <a href="/administration/datenbanken/schild-nrw-daten-in-eine-andere-datenbank-uebertragen-migrieren-tutorial.html">Eine Datenbank migrieren und mit SchILD-NRW 3 verbinden</a> beschreibt die anschließende Connection-Datei. Historische SchILD-Dialoge sind unter <a href="/hilfe/fruehere-verfahren.html">Frühere Verfahren</a> zugänglich.</p><h2 id="sichern-und-wiederherstellen" tabindex="-1">Sichern und wiederherstellen <a class="header-anchor" href="#sichern-und-wiederherstellen" aria-label="Permalink to &quot;Sichern und wiederherstellen&quot;">​</a></h2><ol><li><a href="/administration/datenbanken/datenbank-sichern-verwaltung-datenbank.html">Die Datenbank sichern</a> und ein für den Windows-Benutzer erreichbares Sicherungsverzeichnis wählen.</li><li>Bei Bedarf <a href="/administration/datenbanken/datenbank-wiederherstellen-verwaltung-datenbank.html">Eine Datenbanksicherung wiederherstellen</a>. Die aktuelle Datenbank wird überschrieben; andere Benutzer müssen sich abmelden.</li></ol><p>Eine Arbeitssicherung in derselben Serverumgebung ersetzt kein unabhängiges Backup gegen Serverausfall oder Datenverlust. Die Abgrenzung ist in der Sicherungsanleitung erläutert.</p><h2 id="die-verbindung-erhalten" tabindex="-1">Die Verbindung erhalten <a class="header-anchor" href="#die-verbindung-erhalten" aria-label="Permalink to &quot;Die Verbindung erhalten&quot;">​</a></h2><p>Die Anleitung <a href="/administration/datenbanken/datenbankverbindung-durch-automatische-pings-am-leben-erhalten-tutorial.html">Die Datenbankverbindung durch Pings aufrechterhalten</a> beschreibt die entsprechende Einstellung in Admin.ini. Für die Begriffe und Rollen verwenden Sie <a href="/einstieg/grundlagen/faq.html">Datenbank, Benutzer und Ordner verstehen</a>.</p>',10)])])}const g=n(t,[["render",d]]);export{o as __pageData,g as default};
